243     template<typename T, qualifier Q, bool Aligned>
244     struct compute_determinant<2, 2, T, Q, Aligned>
245     {
246         GLM_FUNC_QUALIFIER static T call(mat<2, 2, T, Q> const& m)
247         {
248             return m[0][0] * m[1][1] - m[1][0] * m[0][1];
249         }
250     };
251 
252     template<typename T, qualifier Q, bool Aligned>
253     struct compute_determinant<3, 3, T, Q, Aligned>
254     {
255         GLM_FUNC_QUALIFIER static T call(mat<3, 3, T, Q> const& m)
256         {
257             return
258                 + m[0][0] * (m[1][1] * m[2][2] - m[2][1] * m[1][2])
259                 - m[1][0] * (m[0][1] * m[2][2] - m[2][1] * m[0][2])
260                 + m[2][0] * (m[0][1] * m[1][2] - m[1][1] * m[0][2]);
261         }
262     };
263 
264     template<typename T, qualifier Q, bool Aligned>
265     struct compute_determinant<4, 4, T, Q, Aligned>
266     {
267         GLM_FUNC_QUALIFIER static T call(mat<4, 4, T, Q> const& m)
268         {
269             T SubFactor00 = m[2][2] * m[3][3] - m[3][2] * m[2][3];
270             T SubFactor01 = m[2][1] * m[3][3] - m[3][1] * m[2][3];
271             T SubFactor02 = m[2][1] * m[3][2] - m[3][1] * m[2][2];
272             T SubFactor03 = m[2][0] * m[3][3] - m[3][0] * m[2][3];
273             T SubFactor04 = m[2][0] * m[3][2] - m[3][0] * m[2][2];
274             T SubFactor05 = m[2][0] * m[3][1] - m[3][0] * m[2][1];
275 
276             vec<4, T, Q> DetCof(
277                 + (m[1][1] * SubFactor00 - m[1][2] * SubFactor01 + m[1][3] * SubFactor02),
278                 - (m[1][0] * SubFactor00 - m[1][2] * SubFactor03 + m[1][3] * SubFactor04),
279                 + (m[1][0] * SubFactor01 - m[1][1] * SubFactor03 + m[1][3] * SubFactor05),
280                 - (m[1][0] * SubFactor02 - m[1][1] * SubFactor04 + m[1][2] * SubFactor05));
281 
282             return
283                 m[0][0] * DetCof[0] + m[0][1] * DetCof[1] +
284                 m[0][2] * DetCof[2] + m[0][3] * DetCof[3];
285         }
286     };
