302     template<typename T, qualifier Q, bool Aligned>
303     struct compute_inverse<2, 2, T, Q, Aligned>
304     {
305         GLM_FUNC_QUALIFIER static mat<2, 2, T, Q> call(mat<2, 2, T, Q> const& m)
306         {
307             T OneOverDeterminant = static_cast<T>(1) / (
308                 + m[0][0] * m[1][1]
309                 - m[1][0] * m[0][1]);
310 
311             mat<2, 2, T, Q> Inverse(
312                 + m[1][1] * OneOverDeterminant,
313                 - m[0][1] * OneOverDeterminant,
314                 - m[1][0] * OneOverDeterminant,
315                 + m[0][0] * OneOverDeterminant);
316 
317             return Inverse;
318         }
319     };
320 
321     template<typename T, qualifier Q, bool Aligned>
322     struct compute_inverse<3, 3, T, Q, Aligned>
323     {
324         GLM_FUNC_QUALIFIER static mat<3, 3, T, Q> call(mat<3, 3, T, Q> const& m)
325         {
326             T OneOverDeterminant = static_cast<T>(1) / (
327                 + m[0][0] * (m[1][1] * m[2][2] - m[2][1] * m[1][2])
328                 - m[1][0] * (m[0][1] * m[2][2] - m[2][1] * m[0][2])
329                 + m[2][0] * (m[0][1] * m[1][2] - m[1][1] * m[0][2]));
330 
331             mat<3, 3, T, Q> Inverse;
332             Inverse[0][0] = + (m[1][1] * m[2][2] - m[2][1] * m[1][2]) * OneOverDeterminant;
333             Inverse[1][0] = - (m[1][0] * m[2][2] - m[2][0] * m[1][2]) * OneOverDeterminant;
334             Inverse[2][0] = + (m[1][0] * m[2][1] - m[2][0] * m[1][1]) * OneOverDeterminant;
335             Inverse[0][1] = - (m[0][1] * m[2][2] - m[2][1] * m[0][2]) * OneOverDeterminant;
336             Inverse[1][1] = + (m[0][0] * m[2][2] - m[2][0] * m[0][2]) * OneOverDeterminant;
337             Inverse[2][1] = - (m[0][0] * m[2][1] - m[2][0] * m[0][1]) * OneOverDeterminant;
338             Inverse[0][2] = + (m[0][1] * m[1][2] - m[1][1] * m[0][2]) * OneOverDeterminant;
339             Inverse[1][2] = - (m[0][0] * m[1][2] - m[1][0] * m[0][2]) * OneOverDeterminant;
340             Inverse[2][2] = + (m[0][0] * m[1][1] - m[1][0] * m[0][1]) * OneOverDeterminant;
341 
342             return Inverse;
343         }
344     };
